"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["53673"],{91574(e){e.exports=JSON.parse('{"id":"FIN-1123","slug":"cohort-analysis","term":"Cohort Analysis","also_known_as":[],"difficulty":"Advanced","definition":"Cohort analysis is a method of studying groups of customers who share a common starting point, such as the month they signed up, to see how their behaviour, such as retention or spending, changes over time.","explanation":["Looking at all customers together can hide important patterns. Cohort analysis separates customers by when they joined, so each group\'s behaviour can be tracked and compared.","For example, an app company might find that 40% of customers who joined in January are still active after six months, while 55% of those who joined in June are still active after six months. This suggests that recent product improvements have increased retention.","Cohort analysis is widely used by subscription businesses, online retailers, mobile apps and lenders. Common measures include retention rates, revenue per customer over time, repeat purchase rates and default rates for groups of loans issued in the same period.","It helps businesses judge whether growth is healthy. Total revenue can rise because many new customers are joining, even while each cohort is leaving quickly. Cohort analysis reveals this. It also shows the effects of changes in marketing, pricing or product features on new customers."],"note":"","total":1500,"prev":{"slug":"coefficient-of-determination","term":"Coefficient of Determination (R-Squared)"},"next":{"slug":"coinsurance","term":"Coinsurance"}}')}}]);